previewCss:
.darma-loader-darma-b14-roller-coaster { --accent: var(--loader-color, #e11d48); --accent-2: var(--loader-secondary-color, #475569); width: var(--loader-size, 120px); height: calc(var(--loader-size, 120px) * .68); position: relative; overflow: hidden; }
.darma-loader-darma-b14-roller-coaster::before { content: ''; position: absolute; bottom: 18%; left: 0; width: 100%; height: 48%; border: calc(var(--loader-size, 120px) * .028) solid var(--accent-2); border-bottom: 0; border-radius: 50% 50% 0 0 / 100% 100% 0 0; }
.darma-loader-darma-b14-roller-coaster::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 20%; border-bottom: calc(var(--loader-size, 120px) * .028) solid color-mix(in srgb, #000 30%, var(--accent-2)); background: repeating-linear-gradient(90deg, color-mix(in srgb, #000 22%, var(--accent-2)) 0 2.5%, transparent 2.5% 16%); }
.darma-loader-darma-b14-roller-coaster span { position: absolute; width: 17%; height: 13%; border-radius: 3px 3px 5px 5px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 24%, var(--accent))); animation: darma-loader-darma-b14-roller-coaster-coast calc(var(--loader-speed, 1s) * 2.8) linear infinite; }
.darma-loader-darma-b14-roller-coaster span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * -1.1); }
@keyframes darma-loader-darma-b14-roller-coaster-coast { 0% { left: -20%; top: 62%; } 16% { left: -1%; top: 42%; } 34% { left: 16%; top: 27%; } 50% { left: 41%; top: 21%; } 66% { left: 66%; top: 27%; } 84% { left: 83%; top: 42%; } 100% { left: 104%; top: 62%; } }

